#!/usr/bin/env python3
"""Patch the known untouched Minecraft 0.15.10 x86 executable for the universal win32craft.dll."""
from __future__ import annotations
import argparse, hashlib, struct
from pathlib import Path

EXPECTED_SHA256 = "028755dff77f8c7f54c4feeb7b5bb522a4d52431cecd2950705b1d1621efaa07"
OUTPUT_SHA256 = "bcce3be80f934ccd4c3ec5d5a4f0d590d58c0853a83331ddbd3476bd00794a38"
PATCHES = [
    (0x172, "020000000000060002", "010000000000060001"),
    (0x18E, "4091", "0081"),
    (0x1B0, "147cb1001c", "e40cb20044"),
    (0x38107, "85c974088b4920", "8b492085c97405"),
    (0x388070, "55", "c3"),
    (0x87C154, "50576800004000e8ab250100", "ff15280ff200909090909090"),
    (0x988224, "5f57534138325f5838362e646c6c", "2e646c6c00000000000000000000"),
    (0x9F65B0, "5f57534138325f5838362e646c6c", "2e646c6c00000000000000000000"),
    (0xB0EDC0, "000000000000000000000000000000", "77696e333263726166742e646c6c00"),
    (0xB16414, "", ""),
    (0xB16774, "94deb10078deb10060", "02e1b1002cdfb100c6"),
    (0xB16824, "c0df", "7a89"),
    (0xB18161, "5f6170702e444c4c", "2e444c4c00000000"),
    (0xB1B238, "5f4150502e646c6c", "2e646c6c00000000"),
    (0xB1BB7B, "5f4150502e646c6c", "2e646c6c00000000"),
    (0xB1BD20, "5f4150502e646c6c", "2e646c6c00000000"),
    (0xB1ECE4, "", ""),
    (0xB1EF28, "000000", "2c7cb1"),
]

WIN32CRAFT_IMPORT_REDIRECTS = [
    "XINPUTUAP.dll",
    "api-ms-win-core-com-l1-1-1.dll",
    "api-ms-win-core-winrt-error-l1-1-1.dll",
    "api-ms-win-core-winrt-l1-1-0.dll",
    "api-ms-win-core-winrt-string-l1-1-0.dll",
    "api-ms-win-eventing-provider-l1-1-0.dll",
    "api-ms-win-gaming-tcui-l1-1-0.dll",
]

def patch(source: Path, output: Path) -> None:
    original = source.read_bytes()
    digest = hashlib.sha256(original).hexdigest()
    if digest != EXPECTED_SHA256:
        raise ValueError(f"unsupported input SHA-256 {digest}; expected {EXPECTED_SHA256}")
    image = bytearray(original)
    pe_offset = int.from_bytes(image[0x3C:0x40], "little")
    characteristics_offset = pe_offset + 4 + 18
    characteristics = int.from_bytes(
        image[characteristics_offset:characteristics_offset + 2], "little"
    )
    if characteristics != 0x0102:
        raise ValueError(
            f"unexpected PE characteristics 0x{characteristics:04X}"
        )
    image[characteristics_offset:characteristics_offset + 2] = \
        (characteristics | 0x20).to_bytes(2, "little")
    for offset, old_hex, new_hex in PATCHES:
        old = bytes.fromhex(old_hex)
        new = bytes.fromhex(new_hex)
        actual = bytes(image[offset:offset + len(old)])
        if actual != old:
            raise ValueError(
                f"file+0x{offset:X} contains {actual.hex()}, expected {old.hex()}"
            )
        if len(old) != len(new):
            raise ValueError("internal patch length mismatch")
        image[offset:offset + len(old)] = new
    # The added import table occupies the existing import directory slot.
    pe = int.from_bytes(image[0x3C:0x40], "little")
    optional = pe + 24
    struct.pack_into("<I", image, optional + 0x68, 0x00B20CE4)

    # Several old DLL names are tightly packed; XINPUTUAP.dll is followed
    # immediately by another descriptor name, so an in-place longer rename
    # corrupts it. Make all redirected descriptors share a reserved string.
    section_count = struct.unpack_from("<H", image, pe + 6)[0]
    optional_size = struct.unpack_from("<H", image, pe + 20)[0]
    section_table = optional + optional_size
    sections = []
    for index in range(section_count):
        section = section_table + index * 40
        vsize, va, raw_size, raw = struct.unpack_from("<4I", image, section + 8)
        sections.append((va, max(vsize, raw_size), raw))

    def rva_to_offset(rva: int) -> int:
        for va, size, raw in sections:
            if va <= rva < va + size:
                return raw + rva - va
        raise ValueError(f"unmapped RVA 0x{rva:X}")

    def offset_to_rva(offset: int) -> int:
        for index, (va, size, raw) in enumerate(sections):
            raw_size = struct.unpack_from(
                "<I", image, section_table + index * 40 + 16
            )[0]
            if raw <= offset < raw + raw_size:
                return va + offset - raw
        raise ValueError(f"unmapped file offset 0x{offset:X}")

    import_offset = rva_to_offset(0x00B20CE4)
    redirects = set(WIN32CRAFT_IMPORT_REDIRECTS)
    redirected = []
    for index in range(32):
        descriptor_offset = import_offset + index * 20
        fields = struct.unpack_from("<5I", image, descriptor_offset)
        if not any(fields):
            break
        name_offset = rva_to_offset(fields[3])
        end = image.find(b"\0", name_offset)
        name = bytes(image[name_offset:end]).decode("ascii")
        if name in redirects:
            redirected.append(descriptor_offset)
    if len(redirected) != len(redirects):
        raise ValueError(f"redirected {len(redirected)} of {len(redirects)} imports")
    shared_name_offset = 0xB0EDC0
    shared_name_rva = offset_to_rva(shared_name_offset)
    image[shared_name_offset:shared_name_offset + 15] = b"win32craft.dll\0"
    for descriptor_offset in redirected:
        struct.pack_into("<I", image, descriptor_offset + 12, shared_name_rva)
    result = hashlib.sha256(image).hexdigest()
    if OUTPUT_SHA256 and result != OUTPUT_SHA256:
        raise ValueError(f"output verification failed: {result} != {OUTPUT_SHA256}")
    output.write_bytes(image)
    print(f"created {output}")
    print(f"SHA-256 {result}")

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("source", nargs="?", type=Path, default=Path("Minecraft.Win10.DX11.exe"))
    parser.add_argument("output", nargs="?", type=Path, default=Path("Win32Craft.0.15.10.exe"))
    args = parser.parse_args()
    patch(args.source, args.output)

if __name__ == "__main__":
    main()
